<template id="line-template"><div class="quote-line grid gap-2 rounded border p-3 md:grid-cols-12"><select class="rounded border-slate-300 md:col-span-2 price-list-item" data-field="price_list_item_id"><option value="">Manual price</option>@foreach($priceListItems as $item)<option value="{{ $item->id }}" data-description="{{ $item->description }}" data-unit-price="{{ $item->unit_price }}" data-pricing-type="{{ $item->pricing_type }}" data-billing-period="{{ $item->billing_period }}" data-service-line="{{ $item->service_line_id }}" data-service-package="{{ $item->service_package_id }}">{{ $item->price_list_name }} · {{ $item->description }} · {{ $item->currency }} {{ number_format((float)$item->unit_price,2) }}</option>@endforeach</select><input class="md:col-span-3 rounded border-slate-300" data-field="description" placeholder="Product or service" required><select class="rounded border-slate-300" data-field="service_line_id"><option value="">No service line</option>@foreach($serviceLines as $serviceLine)<option value="{{ $serviceLine->id }}">{{ $serviceLine->name }}</option>@endforeach</select><select class="rounded border-slate-300" data-field="service_package_id"><option value="">No package</option>@foreach($servicePackages as $package)<option value="{{ $package->id }}">{{ $package->name }}</option>@endforeach</select><select class="rounded border-slate-300" data-field="pricing_type"><option value="fixed">Fixed</option><option value="recurring">Recurring</option><option value="usage">Usage based</option><option value="negotiated">Negotiated</option></select><input class="rounded border-slate-300" type="number" step="0.001" min="0.001" value="1" data-field="quantity" placeholder="Qty" required><input class="rounded border-slate-300" type="number" step="0.01" min="0" data-field="unit_price" placeholder="Unit price" required><input class="rounded border-slate-300" data-field="billing_period" placeholder="Period"><button type="button" class="remove-line rounded border px-2">Remove</button></div></template>
<script>let quoteLineIndex={{ count($lines) }};document.getElementById('add-line').addEventListener('click',()=>{const row=document.getElementById('line-template').content.firstElementChild.cloneNode(true);row.querySelectorAll('[data-field]').forEach(el=>{el.name=`lines[${quoteLineIndex}][${el.dataset.field}]`;el.removeAttribute('data-field')});document.getElementById('quote-lines').appendChild(row);quoteLineIndex++});document.getElementById('quote-lines').addEventListener('change',e=>{if(!e.target.classList.contains('price-list-item'))return;const o=e.target.selectedOptions[0],r=e.target.closest('.quote-line');if(!o.value)return;r.querySelector('[name$="[description]"]').value=o.dataset.description;r.querySelector('[name$="[unit_price]"]').value=o.dataset.unitPrice;r.querySelector('[name$="[pricing_type]"]').value=o.dataset.pricingType;r.querySelector('[name$="[billing_period]"]').value=o.dataset.billingPeriod;r.querySelector('[name$="[service_line_id]"]').value=o.dataset.serviceLine||'';r.querySelector('[name$="[service_package_id]"]').value=o.dataset.servicePackage||''});document.getElementById('quote-lines').addEventListener('click',e=>{if(e.target.classList.contains('remove-line')&&document.querySelectorAll('.quote-line').length>1)e.target.closest('.quote-line').remove()});</script>
